export const getArticle = (id) => articles.find((a) => a.id === Number(id));

// Same-category articles first, then others, excluding the current one.
export const getRelated = (id, count = 3) => {
  const cur = getArticle(id);
  if (!cur) return [];
  const others = articles.filter((a) => a.id !== cur.id);
  const same = others.filter((a) => a.category === cur.category);
  const rest = others.filter((a) => a.category !== cur.category);
  return [...same, ...rest].slice(0, count);
};

